  {"g3:08278091", "Please wait.\\n... ... B Button: Cancel", "Aguarde....\\n... ... BotÃo B: Cancelar"},
  {"g3:082781c7", "Someone is not ready to link.\\n\\nPlease come back after everyone\\nhas made preparations.", "Someone is not ready to link.\\n\\nPlease come back after everyone\\nhas made preparations."},
